import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_tanh(torch::Tensor x);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cstdint>
#include <algorithm>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void cute_tanh_vector_kernel(
    const float* input,
    float* output,
    int64_t numel)
{
    const int64_t vector_numel = numel / 4;
    auto input_tensor = make_tensor(
        make_gmem_ptr(reinterpret_cast<const float4*>(input)),
        make_shape(vector_numel),
        make_stride(Int<1>{}));
    auto output_tensor = make_tensor(
        make_gmem_ptr(reinterpret_cast<float4*>(output)),
        make_shape(vector_numel),
        make_stride(Int<1>{}));
    int64_t index = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    int64_t step = static_cast<int64_t>(blockDim.x) * gridDim.x;
    for (int64_t i = index; i < vector_numel; i += step) {
        float4 value = input_tensor(i);
        value = make_float4(
            __tanhf(value.x), __tanhf(value.y),
            __tanhf(value.z), __tanhf(value.w));
        output_tensor(i) = value;
    }
    for (int64_t i = vector_numel * 4 + index; i < numel; i += step) {
        output[i] = __tanhf(input[i]);
    }
}
__global__ void cute_tanh_kernel(
    const float* input,
    float* output,
    int64_t numel)
{
    auto input_tensor = make_tensor(
        make_gmem_ptr(input),
        make_shape(numel),
        make_stride(Int<1>{}));
    auto output_tensor = make_tensor(
        make_gmem_ptr(output),
        make_shape(numel),
        make_stride(Int<1>{}));
    int64_t index = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    int64_t step = static_cast<int64_t>(blockDim.x) * gridDim.x;
    for (int64_t i = index; i < numel; i += step) {
        output_tensor(i) = __tanhf(input_tensor(i));
    }
}
torch::Tensor cute_tanh(torch::Tensor x)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    auto x_contiguous = x.contiguous();
    auto output = torch::empty_like(x_contiguous);
    const int64_t numel = x_contiguous.numel();
    if (numel == 0) {
        return output;
    }
    constexpr int threads = 256;
    const bool aligned =
        (reinterpret_cast<std::uintptr_t>(x_contiguous.data_ptr<float>()) & 0xF) == 0 &&
        (reinterpret_cast<std::uintptr_t>(output.data_ptr<float>()) & 0xF) == 0;
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    if (aligned) {
        const int64_t vector_numel = numel / 4;
        int blocks = static_cast<int>((vector_numel + threads - 1) / threads);
        blocks = blocks > 0 ? blocks : 1;
        blocks = std::min(blocks, 4096);
        cute_tanh_vector_kernel<<<blocks, threads, 0, stream>>>(
            x_contiguous.data_ptr<float>(),
            output.data_ptr<float>(),
            numel);
    } else {
        int blocks = static_cast<int>((numel + threads - 1) / threads);
        blocks = std::min(blocks, 4096);
        cute_tanh_kernel<<<blocks, threads, 0, stream>>>(
            x_contiguous.data_ptr<float>(),
            output.data_ptr<float>(),
            numel);
    }
    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE tanh kernel launch failed");
    return output;
}

"""


cute_ext = load_inline(
    name="cute_tanh_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_tanh"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_tanh(x)

